      editMessages: [{ chatId: ownerId, messageId: cb.message?.message_id, text: ownerUpdatedText }],
      messagesToSend: isApproved ? [{
        chatId: candidateId,
        text: '✅ *Доступ підтверджено!* Тепер ви отримуватимете сповіщення про нові статті для сайту HomeLabCore.dev і зможете схвалювати або відхиляти їх публікацію.'
      }] : []
    }
  }];
}

// 3. Handle Publication Approval / Rejection (p|<a|r>|<draftId>|<sha10>|<sig> or legacy hlc-pub|...)
const isV2 = rawData.startsWith('p|');
const isLegacy = rawData.startsWith('hlc-pub|');
if (!isV2 && !isLegacy) {
  return [];
}

if (!actorId || actorId !== actorChatId || !authUsers.includes(actorId)) {
  throw new Error('Unauthorized Telegram user or chat ID');
}

let action = '';
let draftKey = '';
const pending = { ...(state.pendingDrafts || {}) };

if (isV2) {
  const parts = rawData.split('|');
  if (parts.length !== 5) {
    throw new Error('Malformed v2 publication callback_data');
  }
  const [, shortAct, draftId, sha10, sig] = parts;
  if (!['a', 'r'].includes(shortAct)) {
    return [];
  }
  action = shortAct === 'a' ? 'approve' : 'reject';
  draftKey = draftId;
  const draft = pending[draftKey];
  if (!draft) {
    return [];
  }
  if (!String(draft.reviewedCommitSha || '').startsWith(sha10)) {
    throw new Error('Callback commit SHA prefix mismatch');
  }
  const expectedSig = hmacSha256Hex(cbSecret, `p|${shortAct}|${draftId}|${sha10}|${draft.reviewedCommitSha}`).slice(0, 16);
  if (!safeEq(sig, expectedSig)) {
    throw new Error('Invalid callback_data HMAC signature');
  }
} else {
  const parts = rawData.split('|');
  if (parts.length !== 4) {
    throw new Error('Malformed hlc-pub callback_data');
  }
  const [, act, shortSlug, sig] = parts;
  if (!['approve', 'reject'].includes(act)) {
    return [];
  }
  const expectedSig = hmacSha256Hex(cbSecret, `hlc-pub|${act}|${shortSlug}`).slice(0, 16);
  if (!safeEq(sig, expectedSig)) {
    throw new Error('Invalid callback_data HMAC signature');
  }
  action = act;
  draftKey = shortSlug;
}

const draft = pending[draftKey];
if (!draft) {
  return [];
}
if (body.update_id !== undefined) {
  state.seenUpdateIds = [...seen, body.update_id].slice(-200);
}

// First valid approval or rejection wins
if (draft.status !== 'pending') {
  return [{
    json: {
      mode: 'already_decided',
      callbackQueryId: String(cb.id || ''),
      toastText: 'ℹ️ Рішення щодо цієї статті вже прийнято.',
      editMessages: [],
      messagesToSend: []
    }
  }];
}

const isApproved = action === 'approve';
pending[draftKey] = {
  ...draft,
  status: isApproved ? 'approved' : 'rejected',
  decidedBy: actorId,
  decidedByName: actorName,
  decidedAt: new Date().toISOString()
};
state.pendingDrafts = pending;

const processed = { ...(state.processedEvents || {}) };
processed[draft.sourceEventId] = isApproved ? 'approved' : 'rejected';
state.processedEvents = processed;

const statusLine = isApproved
  ? `✅ *Статус:* Схвалено (${actorName}) — перевіряємо CI та публікуємо на сайт...`
  : `🛑 *Статус:* Відхилено (${actorName}) — чернетку PR закрито, стаття не публікуватиметься.`;

const updatedMessageText = [
  '📰 *Нова стаття для сайту HomeLabCore*',
  '',
  `*Проєкт:* ${draft.projectName || 'HomeLabCore'}`,
  `*Заголовок:* ${draft.title}`,
  ...(draft.prUrl ? [`🔗 [Чернетка PR #${draft.prNumber}](${draft.prUrl})`] : []),
  '',
  statusLine
].join('\n');

const targetMessages = Array.isArray(draft.messages) && draft.messages.length > 0
  ? draft.messages
  : [{ chatId: actorChatId, messageId: cb.message?.message_id }];

return [{
  json: {
    mode: 'publication_decision',
    decision: action,
    approved: isApproved,
    draftId: draftKey,
    slug: draft.slug,
    filePath: draft.filePath,
    branchName: draft.branchName,
    projectName: draft.projectName || 'HomeLabCore',
    title: draft.title,
    prNumber: draft.prNumber,
    prUrl: draft.prUrl,
    prNodeId: draft.prNodeId,
    reviewedCommitSha: draft.reviewedCommitSha,
    liveUrl: draft.liveUrl || `https://homelabcore.dev/blog/${draft.slug}/`,
    authorizedUsers: authUsers,
    callbackQueryId: String(cb.id || ''),
    toastText: isApproved ? '✅ Схвалено — перевіряємо CI та публікуємо статтю' : '🛑 Відхилено — чернетку PR буде закрито',
    editMessages: targetMessages.map((m) => ({
      chatId: String(m.chatId),
      messageId: m.messageId,
      text: updatedMessageText
    }))
  }
}];

const info = $('Verify HomeLab Info Owner Authorization').first().json;
const edits = Array.isArray(info.editMessages) ? info.editMessages : [];
if (edits.length === 0) {
  return [{ json: { skipEdit: true, chatId: '0', messageId: 0, text: '' } }];
}
return edits.map((e) => ({ json: { skipEdit: false, chatId: String(e.chatId), messageId: e.messageId, text: String(e.text) } }));

const prev = $node['Gate Approved Decision'].json;
const pr = $('Fetch PR State on GitHub').first().json;
const checksResp = $('Fetch Commit Check Runs').first().json;
const pollCount = Number(prev.ciPollCount || 0);

if (!pr || pr.state !== 'open') {
  return [{
    json: {
      ...prev,
      readyToMerge: false,
      waitForCi: false,
      abortReason: 'Чернетка PR вже закрита або недоступна.'
    }
  }];
}

const actualSha = String(pr.head?.sha || '');
if (!actualSha || actualSha !== String(prev.reviewedCommitSha)) {
  return [{
    json: {
      ...prev,
      readyToMerge: false,
      waitForCi: false,
      shaMismatch: true,
      abortReason: 'Вміст PR було змінено після створення чернетки (SHA коміту не збігається з перевіреним). Публікацію зупинено.'
    }
  }];
}

const runs = Array.isArray(checksResp.check_runs) ? checksResp.check_runs : [];
const failing = runs.filter((r) => r.status === 'completed' && !['success', 'neutral', 'skipped'].includes(String(r.conclusion || '')));
if (failing.length > 0) {
  return [{
    json: {
      ...prev,
      readyToMerge: false,
      waitForCi: false,
      ciFailed: true,
      abortReason: `Перевірка CI завершилася помилкою (${failing.map((f) => f.name).join(', ')}).`
    }
  }];
}

const pending = runs.filter((r) => r.status !== 'completed');
if ((runs.length === 0 || pending.length > 0) && pollCount < 18) {
  return [{
    json: {
      ...prev,
      ciPollCount: pollCount + 1,
      readyToMerge: false,
      waitForCi: true
    }
  }];
}

if (pending.length > 0) {
  return [{
    json: {
      ...prev,
      readyToMerge: false,
      waitForCi: false,
      abortReason: `Перевірки CI тривають довше очікуваного (${pending.map((p) => p.name).join(', ')}).`
    }
  }];
}

return [{
  json: {
    ...prev,
    prNodeId: pr.node_id || prev.prNodeId,
    readyToMerge: true,
    waitForCi: false
  }
}];

const state = $getWorkflowStaticData('global');
const info = $('Gate Ready to Merge').first().json;
const mergeRes = $('Merge Approved PR with SHA Guard').first().json;
const isMerged = Boolean(mergeRes && mergeRes.merged === true);

const users = Array.isArray(info.authorizedUsers) && info.authorizedUsers.length > 0
  ? info.authorizedUsers
  : [String(state.config?.ownerTelegramId || '')];

if (isMerged) {
  const pending = { ...(state.pendingDrafts || {}) };
  if (pending[info.draftId]) {
    pending[info.draftId] = { ...pending[info.draftId], status: 'merged', mergedAt: new Date().toISOString() };
    state.pendingDrafts = pending;
  }
  const processed = { ...(state.processedEvents || {}) };
  if (pending[info.draftId]?.sourceEventId) {
    processed[pending[info.draftId].sourceEventId] = 'merged';
    state.processedEvents = processed;
  }
  const text = [
    '🚀 *Статтю опубліковано на HomeLabCore.dev!*',
    '',
    `*Проєкт:* ${info.projectName}`,
    `*Заголовок:* ${info.title}`,
    '',
    `🌐 *Читати на сайті:* ${info.liveUrl}`,
    `🔗 [Переглянути PR #${info.prNumber}](${info.prUrl})`
  ].join('\n');
  return users.map((chatId) => ({ json: { chatId: String(chatId), text } }));
} else {
  const errMsg = mergeRes?.message || 'Не вдалося виконати автоматичне злиття PR.';
  const text = [
    '⚠️ *Автоматичне злиття потребує уваги*',
    '',
    `*Проєкт:* ${info.projectName}`,
    `*Заголовок:* ${info.title}`,
    `*Причина:* ${errMsg}`,
    '',
    `🔗 Перевірте PR вручну: ${info.prUrl}`
  ].join('\n');
  return users.map((chatId) => ({ json: { chatId: String(chatId), text } }));
}

const state = $getWorkflowStaticData('global');
const item = $input.first().json;
const users = Array.isArray(item.authorizedUsers) && item.authorizedUsers.length > 0
  ? item.authorizedUsers
  : [String(state.config?.ownerTelegramId || '')];

if (item.mode === 'enrollment_decision' || item.mode === 'direct_messages') {
  const msgs = Array.isArray(item.messagesToSend) ? item.messagesToSend : [];
  return msgs.map((m) => ({ json: { chatId: String(m.chatId), text: String(m.text) } }));
}

if (item.decision === 'reject') {
  const text = [
    '🛑 *Публікацію скасовано*',
    '',
    `*Проєкт:* ${item.projectName}`,
    `*Заголовок:* ${item.title}`,
    '',
    `Чернетку [PR #${item.prNumber}](${item.prUrl}) закрито, гілку видалено. Стаття не була опублікована.`
  ].join('\n');
  return users.map((chatId) => ({ json: { chatId: String(chatId), text } }));
}

if (item.abortReason) {
  const text = [
    '⚠️ *Автоматична публікація зупинена*',
    '',
    `*Проєкт:* ${item.projectName}`,
    `*Заголовок:* ${item.title}`,
    `*Причина:* ${item.abortReason}`,
    '',
    `🔗 Перевірте PR вручну: ${item.prUrl}`
  ].join('\n');
  return users.map((chatId) => ({ json: { chatId: String(chatId), text } }));
}

return [];
